@layer moduix.components {
  .root {
    display: inline-grid;
    place-items: center;
    gap: var(--moduix-spacing-3);
    width: max-content;
    max-inline-size: 100%;
    color: var(--moduix-color-foreground);
  }

  .area {
    display: inline-flex;
    min-inline-size: 0;
    max-inline-size: 100%;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: center;
    gap: var(--moduix-spacing-1);
    font-size: var(--moduix-text-2xl);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-2xl);
    font-variant-numeric: tabular-nums;
  }

  .item {
    min-width: 2ch;
    text-align: center;
  }

  .separator {
    color: var(--moduix-color-muted-foreground);
  }

  .control {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--moduix-spacing-2);
  }

  .actionTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-md);
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1-5) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    appearance: none;
    font: inherit;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    white-space: nowrap;
    cursor: pointer;
    transition: background-color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:disabled {
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
      pointer-events: none;
    }

    &[hidden] {
      display: none;
    }

    & :where(svg) {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }
}

import { TimerContext, useTimer, useTimerContext } from '@ark-ui/vue/timer';
import Timer from './Timer.vue';
import TimerActionTrigger from './TimerActionTrigger.vue';
import TimerArea from './TimerArea.vue';
import TimerControl from './TimerControl.vue';
import TimerItem from './TimerItem.vue';
import TimerRootProvider from './TimerRootProvider.vue';
import TimerSegments from './TimerSegments.vue';
import TimerSeparator from './TimerSeparator.vue';

export {
  Timer,
  TimerActionTrigger,
  TimerArea,
  TimerContext,
  TimerControl,
  TimerItem,
  TimerRootProvider,
  TimerSegments,
  TimerSeparator,
  useTimer,
  useTimerContext,
};

export type { Props as TimerSegmentsProps } from './TimerSegments.vue';
export type { TimerTickDetails } from './Timer.vue';

export type {
  TimerActionTriggerBaseProps,
  TimerActionTriggerProps,
  TimerAreaBaseProps,
  TimerAreaProps,
  TimerContextProps,
  TimerControlBaseProps,
  TimerControlProps,
  TimerItemBaseProps,
  TimerItemProps,
  TimerRootEmits,
  TimerRootProps,
  TimerRootProviderBaseProps,
  TimerRootProviderProps,
  TimerSeparatorBaseProps,
  TimerSeparatorProps,
  UseTimerContext,
  UseTimerProps,
  UseTimerReturn,
} from '@ark-ui/vue/timer';
